package alphametics

import "testing"

func TestExtra(t *testing.T) {
	// trivially solvable single-letter puzzle
	if m, err := Solve("A + A == B"); err != nil || m["A"] != 5 || m["B"] != 0 {
		t.Fatalf("A + A == B: %v %v", m, err)
