{"operation":"bash","command":"cat > alphametics.go <<'EOF'
package alphametics

import (
	"errors"
	"strings"
)

type column struct {
	counts [26]int
	result int
}

// Solve returns a mapping from letters to digits that solves the alphametics
// puzzle, or an error if no solution exists.
func Solve(puzzle string) (map[string]int, error) {
	parts := strings.Split(puzzle, "==")
	if len(parts) != 2 {
		return nil, errors.New("invalid puzzle: expected exactly one ==")
	}

	parseSide := func(s string) ([]string, bool) {
		raw := strings.Split(s, "+")
		words := make([]string, 0, len(raw))
		for _, w := range raw {
			w = strings.ReplaceAll(w, " ", "")
			w = strings.ReplaceAll(w, "\t", "")
			if w == "" {
				return nil, false
			}
			words = append(words, w)
		}
		return words, true
	}

	addends, ok := parseSide(strings.TrimSpace(parts[0]))
	if !ok {
		return nil, errors.New("invalid puzzle: empty addend")
	}
	resultWords, ok := parseSide(strings.TrimSpace(parts[1]))
	if !ok || len(resultWords) != 1 {
		return nil, errors.New("invalid puzzle: expected exactly one result word")
	}
	result := resultWords[0]

	maxLen := len(result)
	for _, w := range addends {
		if len(w) > maxLen {
			maxLen = len(w)
		}
	}

	var leading [26]bool
	for _, w := range addends {
		if len(w) > 1 {
			leading[w[0]-'A'] = true
		}
	}
	if len(result) > 1 {
		leading[result[0]-'A'] = true
	}

	cols := make([]column, maxLen)
	for i := range cols {
		cols[i].result = -1
	}

	for _, w := range addends {
		for i := 0; i < len(w); i++ {
			letter := w[len(w)-1-i] - 'A'
			cols[i].counts[letter]++
		}
	}
	for i := 0; i < len(result); i++ {
		cols[i].result = int(result[len(result)-1-i] - 'A')
	}

	var assign [26]int
	for i := range assign {
		assign[i] = -1
	}
	var used [10]bool

	var dfs func(col, carry int) bool
	dfs = func(col, carry int) bool {
		if col == maxLen {
			return carry == 0
		}

		c := &cols[col]
		var unknown [26]int
		n := 0
		for letter := 0; letter < 26; letter++ {
			if c.counts[letter] > 0 && assign[letter] < 0 {
				unknown[n] = letter
				n++
			}
		}

		var try func(k, sum int) bool
		try = func(k, sum int) bool {
			if k == n {
				digit := sum % 10
				nextCarry := sum / 10
				r := c.result

				if r >= 0 {
					if assign[r] >= 0 {
						if assign[r] != digit {
							return false
						}
						return dfs(col+1, nextCarry)
					}
					if used[digit] {
						return false
					}
					if leading[r] && digit == 0 {
						return false
					}
					assign[r] = digit
					used[digit] = true
					found := dfs(col+1, nextCarry)
					used[digit] = false
					assign[r] = -1
					return found
				}

				// A column beyond the result's length has no result digit.
				if digit != 0 {
					return false
				}
				return dfs(col+1, nextCarry)
			}

			letter := unknown[k]
			for digit := 0; digit <= 9; digit++ {
				if used[digit] || (leading[letter] && digit == 0) {
					continue
				}
				used[digit] = true
				assign[letter] = digit
				if try(k+1, sum+c.counts[letter]*digit) {
					return true
				}
				assign[letter] = -1
				used[digit] = false
			}
			return false
		}

		return try(0, carry)
	}

	if !dfs(0, 0) {
		return nil, errors.New("no solution")
	}

	solution := make(map[string]int)
	for letter := 0; letter < 26; letter++ {
		if assign[letter] >= 0 {
			solution[string(rune('A'+letter))] = assign[letter]
		}
	}
	return solution, nil
}
EOF
