					used[digit] = true
					found := dfs(col+1, nextCarry)
					used[digit] = false
					assign[r] = -1
					return found
				}

				// A column beyond the result's length has no result digit.
				if digit != 0 {
					return false
				}
				return dfs(col+1, nextCarry)
			}

			letter := unknown[k]
			for digit := 0; digit <= 9; digit++ {
				if used[digit] || (leading[letter] && digit == 0) {
					continue
				}
				used[digit] = true
				assign[letter] = digit
				if try(k+1, sum+c.counts[letter]*digit) {
