package alphametics

import (
	"math/rand"
	"strings"
	"testing"
)

// brute force reference: try all injective assignments via permutations
func brute(puzzle string) (map[string]int, bool) {
	parts := strings.Split(puzzle, "==")
	lhs := strings.Split(parts[0], "+")
	rhs := strings.TrimSpace(parts[1])
	var words []string
	for _, w := range lhs {
		w = strings.Join(strings.Fields(w), "")
		if w == "" {
			return nil, false
		}
		words = append(words, w)
	}
	letters := map[byte]bool{}
	var order []byte
	for _, w := range append(words, rhs) {
		for i := 0; i < len(w); i++ {
			if !letters[w[i]] {
				letters[w[i]] = true
				order = append(order, w[i])
			}
		}
	}
	if len(order) > 10 {
		return nil, false
	}
	lead := map[byte]bool{}
	for _, w := range append(words, rhs) {
		if len(w) > 1 {
			lead[w[0]] = true
		}
	}
	val := map[byte]int{}
	used := [10]bool{}
	var found map[string]int
	var rec func(k int) bool
	rec = func(k int) bool {
		if found != nil {
			return true // already have one solution; keep unique semantics check outside
		}
		if k == len(order) {
			sum := 0
			for _, w := range words {
				n := 0
				for i := 0; i < len(w); i++ {
					n = n*10 + val[w[i]]
				}
				sum += n
			}
			n := 0
			for i := 0; i < len(rhs); i++ {
				n = n*10 + val[rhs[i]]
			}
			if sum == n {
				m := map[string]int{}
				for l, d := range val {
					m[string(rune(l))] = d
				}
				found = m
				return true
			}
			return false
		}
		l := order[k]
		for d := 0; d <= 9; d++ {
			if used[d] || (lead[l] && d == 0) {
				continue
			}
			used[d] = true
			val[l] = d
			if rec(k + 1) {
				return true
			}
			delete(val, l)
			used[d] = false
		}
		return false
	}
	rec(0)
	if found == nil {
		return nil, false
	}
	return found, true
}

func checkEq(a, b map[string]int) bool {
	if len(a) != len(b) {
		return false
	}
	for k, v := range b {
		if a[k] != v {
			return false
		}
	}
	return true
}

func TestCrossCheckRandom(t *testing.T) {
	rng := rand.New(rand.NewSource(7))
	alpha := []byte("ABCDEFGHIJ")
	for iter := 0; iter < 300; iter++ {
		nw := 1 + rng.Intn(3)
		letters := alpha[:2+rng.Intn(5)]
		mk := func() string {
			l := 1 + rng.Intn(3)
			b := make([]byte, l)
			for i := range b {
				b[i] = letters[rng.Intn(len(letters))]
			}
			return string(b)
		}
		var parts []string
		for i := 0; i < nw; i++ {
			parts = append(parts, mk())
		}
		puzzle := strings.Join(parts, " + ") + " == " + mk()
		got, err := Solve(puzzle)
		want, ok := brute(puzzle)
		if ok != (err == nil) {
			t.Fatalf("%q: solver err=%v, brute ok=%v", puzzle, err, ok)
		}
		if ok && !checkEq(got, want) {
			t.Logf("%q: solver=%v brute=%v (possible alternative solution)", puzzle, got, want)
			// verify both satisfy the equation
			if !satisfies(got, puzzle) {
				t.Fatalf("%q: solver answer %v does not satisfy puzzle", puzzle, got)
			}
			if !satisfies(want, puzzle) {
				t.Fatalf("%q: brute answer %v does not satisfy puzzle", puzzle, want)
			}
		}
	}
}

func satisfies(m map[string]int, puzzle string) bool {
	parts := strings.Split(puzzle, "==")
	if len(parts) != 2 {
		return false
	}
	lead := map[byte]bool{}
	eval := func(w string) (int, bool) {
		w = strings.Join(strings.Fields(w), "")
		if w == "" {
			return 0, false
		}
		if len(w) > 1 && m[string(rune(w[0]))] == 0 {
			return 0, false
		}
		n := 0
		for i := 0; i < len(w); i++ {
			v, ok := m[string(rune(w[i]))]
			if !ok {
				return 0, false
			}
			n = n*10 + v
		}
		return n, true
	}
	sum := 0
	for _, w := range strings.Split(parts[0], "+") {
		v, ok := eval(w)
		if !ok {
			return false
		}
		sum += v
	}
	want, ok := eval(parts[1])
	return ok && sum == want
}

func TestEdge(t *testing.T) {
	if _, err := Solve("A + B"); err == nil {
		t.Fatal("expected error on missing ==")
	}
	if _, err := Solve("A + B == C + D"); err == nil {
		t.Fatal("expected error on multiple result words")
	}
	if m, err := Solve("ABC == ABC"); err != nil || len(m) != 3 {
		t.Fatalf("ABC == ABC: %v %v", m, err)
	}
	if _, err := Solve("A == B"); err == nil {
		t.Fatal("expected error: A == B needs distinct digits but must be equal")
	}
	if _, err := Solve("ACA + DD == BD"); err == nil {
		t.Fatal("expected error: only leading-zero solution")
	}
	if _, err := Solve("I + BB == ILL"); err != nil {
		t.Fatalf("I + BB == ILL failed: %v", err)
	}
}
EOF
